DROP TABLE IF EXISTS `col_movies_tt`;
CREATE TABLE `col_movies_tt` (
  `id` int(5) unsigned NOT NULL,
  `movie_list_id` int(5) unsigned NOT NULL,
  `movie_tt_the` tinyint(1) unsigned NOT NULL,
  `movie_tt` varchar(110) NOT NULL,
  `movie_tt_inf` varchar(110) NOT NULL,
  `movie_type` tinyint(1) unsigned NOT NULL,
  `movie_release` tinyint(1) unsigned NOT NULL,
  `movie_year` year(4) NOT NULL,
  `movie_imdb_id` int(7) unsigned zerofill NOT NULL,
  `movie_imdb_rating` double(3,1) NOT NULL,
  `movie_add_date` date NOT NULL,
  `movie_seen` tinyint(1) unsigned NOT NULL,
  `movie_show` tinyint(1) unsigned NOT NULL,
  PRIMARY KEY  (`id`)
) ENGINE=MyISAM DEFAULT CHARSET=latin1;

